### Managing State and Side Effects

#### useState

```jsx
import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <p>Count: {count}</p>
      {/* Always use the updater form when new state depends on old */}
      <button onClick={() => setCount(prev => prev + 1)}>+</button>
      <button onClick={() => setCount(prev => prev - 1)}>-</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  );
}
```

#### useEffect

```jsx
import { useState, useEffect } from 'react';

function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Runs after every render where userId changed
    let cancelled = false;

    setLoading(true);
    fetchUser(userId).then(data => {
      if (!cancelled) {
        setUser(data);
        setLoading(false);
      }
    });

    // Cleanup: cancel if component unmounts or userId changes
    return () => { cancelled = true; };
  }, [userId]); // Dependency array

  if (loading) return <Spinner />;
  return <div>{user.name}</div>;
}
```

#### Dependency Array Rules

| Array | Runs when |
| :--- | :--- |
| Missing | After every render |
| `[]` | Once, on mount only |
| `[dep1, dep2]` | On mount + when any dep changes |

---

### Performance and DOM Access Hooks

#### useRef

A mutable container that persists across renders without triggering re-renders.

```jsx
import { useRef, useEffect } from 'react';

function VideoPlayer({ src }) {
  const videoRef = useRef(null);

  // Accessing DOM elements
  const play = () => videoRef.current.play();
  const pause = () => videoRef.current.pause();

  return <video ref={videoRef} src={src} />;
}

// Storing mutable values that don't affect rendering
function Timer() {
  const intervalRef = useRef(null);

  const start = () => {
    intervalRef.current = setInterval(() => console.log('tick'), 1000);
  };

  const stop = () => clearInterval(intervalRef.current);

  return <><button onClick={start}>Start</button><button onClick={stop}>Stop</button></>;
}
```

#### useMemo and useCallback

```jsx
import { useMemo, useCallback } from 'react';

function DataGrid({ rows, onRowClick }) {
  // Memoize expensive computation
  const sortedRows = useMemo(() => {
    return [...rows].sort((a, b) => a.name.localeCompare(b.name));
  }, [rows]); // Only re-sort when rows changes

  // Memoize a callback (stable reference for child props)
  const handleClick = useCallback((id) => {
    onRowClick(id);
  }, [onRowClick]);

  return sortedRows.map(row => (
    <Row key={row.id} data={row} onClick={handleClick} />
  ));
}
```

> **Rule**: Don't premature-optimise. Add `useMemo`/`useCallback` only when you've profiled and confirmed a bottleneck.

---

### Avoiding Prop Drilling

Context lets you share state across the component tree without passing props at every level.

```jsx
import { createContext, useContext, useState } from 'react';

// 1. Create the context
const AuthContext = createContext(null);

// 2. Create a provider component
export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  const login = async (email, password) => {
    const user = await api.login(email, password);
    setUser(user);
  };

  const logout = () => setUser(null);

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

// 3. Create a custom hook for safe consumption
export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
}

// 4. Use anywhere in the tree
function Navbar() {
  const { user, logout } = useAuth();
  return (
    <nav>
      {user ? (
        <><span>{user.name}</span><button onClick={logout}>Logout</button></>
      ) : (
        <a href="/login">Login</a>
      )}
    </nav>
  );
}
```

> Context re-renders **all consumers** when the value changes. For high-frequency updates, prefer Zustand or Redux.

---

### When React Apps Get Slow

#### React.memo — Skip Unnecessary Re-renders

```jsx
// Without memo: re-renders every time parent renders
function ExpensiveList({ items }) {
  return items.map(item => <Row key={item.id} item={item} />);
}

// With memo: only re-renders when items prop changes
const ExpensiveList = React.memo(function ExpensiveList({ items }) {
  return items.map(item => <Row key={item.id} item={item} />);
});
```

#### Code Splitting with React.lazy

```jsx
import { lazy, Suspense } from 'react';

// Only loaded when the route is visited
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Analytics = lazy(() => import('./pages/Analytics'));

function App() {
  return (
    <Suspense fallback={<PageSpinner />}>
      <Routes>
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/analytics" element={<Analytics />} />
      </Routes>
    </Suspense>
  );
}
```

#### Profiling

Use the **React DevTools Profiler** tab:
1. Record an interaction.
2. Identify components with unexpectedly long render times.
3. Check if `memo`, `useMemo`, or `useCallback` would help.
4. Look for components rendering too frequently.

